import os
import csv
import json
import math

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"


def read_csv(name):
    path = os.path.join(DATA_DIR, name)
    with open(path, newline="") as fh:
        return list(csv.DictReader(fh))


def main():
    os.makedirs(SUB_DIR, exist_ok=True)

    cages = read_csv("cages.csv")
    feeds = read_csv("feed_options.csv")
    days = read_csv("days.csv")
    cond = read_csv("cage_day_conditions.csv")
    with open(os.path.join(DATA_DIR, "config.json")) as fh:
        cfg = json.load(fh)

    eps = cfg["feasibility_tolerance"]
    o2_gain = cfg["aeration_oxygen_gain_per_hour"]
    aeration_fixed_cost = cfg["aeration_fixed_cost_per_hour"]

    cage_ids = [c["cage_id"] for c in cages]
    day_ids = [d["day"] for d in days]
    feed_ids = [f["feed_id"] for f in feeds]

    cage = {}
    for c in cages:
        cage[c["cage_id"]] = {
            "species": c["species"],
            "biomass": float(c["biomass_tonnes"]),
            "min_feed": float(c["min_feed_kg"]),
            "max_feed": float(c["max_feed_kg"]),
            "min_protein": float(c["min_protein_fraction"]),
            "min_oxygen": float(c["min_oxygen_mg_l"]),
        }

    feed = {}
    for f in feeds:
        feed[f["feed_id"]] = {
            "protein": float(f["protein_fraction"]),
            "fishmeal": float(f["fishmeal_share"]),
            "cost": float(f["cost_per_kg"]),
            "o2load": float(f["oxygen_load_per_kg"]),
        }

    day = {}
    for d in days:
        day[d["day"]] = {
            "base_oxy": float(d["baseline_oxygen_mg_l"]),
            "barge_cap": float(d["feed_barge_capacity_kg"]),
            "aer_limit": float(d["aerator_hour_limit"]),
            "power_cost": float(d["power_cost_per_hour"]),
            "fishmeal_lim": float(d["max_fishmeal_kg"]),
        }

    cond_map = {}
    for r in cond:
        cond_map[(r["cage_id"], r["day"])] = {
            "appetite": float(r["appetite_factor"]),
            "o2sens": float(r["oxygen_sensitivity"]),
        }

    model = Model("coastal_aquaculture")
    model.setMinimize()

    x = {}
    h = {}
    for c in cage_ids:
        for d in day_ids:
            for f in feed_ids:
                x[(c, d, f)] = model.addVar(
                    name=f"x_{c}_{d}_{f}",
                    vtype="C",
                    lb=0.0,
                    ub=float("inf"),
                    obj=feed[f]["cost"],
                )
            h[(c, d)] = model.addVar(
                name=f"h_{c}_{d}",
                vtype="C",
                lb=0.0,
                ub=float("inf"),
                obj=aeration_fixed_cost,
            )

    # 1. Ration band per cage-day
    for c in cage_ids:
        for d in day_ids:
            app = cond_map[(c, d)]["appetite"]
            total = quicksum(x[(c, d, f)] for f in feed_ids)
            model.addCons(
                total >= cage[c]["min_feed"] * app, name=f"minfeed_{c}_{d}"
            )
            model.addCons(
                total <= cage[c]["max_feed"] * app, name=f"maxfeed_{c}_{d}"
            )

    # 2. Blended protein per cage-day
    for c in cage_ids:
        mp = cage[c]["min_protein"]
        for d in day_ids:
            lhs = quicksum(
                (feed[f]["protein"] - mp) * x[(c, d, f)] for f in feed_ids
            )
            model.addCons(lhs >= 0.0, name=f"protein_{c}_{d}")

    # 3. Dissolved oxygen per cage-day
    for c in cage_ids:
        for d in day_ids:
            sens = cond_map[(c, d)]["o2sens"]
            base = day[d]["base_oxy"]
            need = cage[c]["min_oxygen"]
            # base + gain*h - sens*biomass - sum(o2load*x) >= need
            # gain*h - sum(o2load*x) >= need - base + sens*biomass
            rhs = need - base + sens * cage[c]["biomass"]
            lhs = o2_gain * h[(c, d)] - quicksum(
                feed[f]["o2load"] * x[(c, d, f)] for f in feed_ids
            )
            model.addCons(lhs >= rhs, name=f"oxygen_{c}_{d}")

    # 4. Daily barge capacity
    for d in day_ids:
        total = quicksum(x[(c, d, f)] for c in cage_ids for f in feed_ids)
        model.addCons(
            total <= day[d]["barge_cap"], name=f"barge_{d}"
        )

    # 5. Daily aeration hour limit
    for d in day_ids:
        total = quicksum(h[(c, d)] for c in cage_ids)
        model.addCons(total <= day[d]["aer_limit"], name=f"aer_{d}")

    # 6. Daily fishmeal limit
    for d in day_ids:
        total = quicksum(
            feed[f]["fishmeal"] * x[(c, d, f)]
            for c in cage_ids
            for f in feed_ids
        )
        model.addCons(total <= day[d]["fishmeal_lim"], name=f"fishmeal_{d}")

    # Objective already set via addVar obj for feed; add aeration power cost
    # Power cost is per-hour and day-specific, so add it to the objective.
    for c in cage_ids:
        for d in day_ids:
            model.setObjective(
                model.getObjVal() if False else None,
                append=False,
            ) if False else None

    # Add power cost term to objective: (fixed + power_d) * h
    # Rebuild objective cleanly.
    obj_terms = []
    for c in cage_ids:
        for d in day_ids:
            for f in feed_ids:
                obj_terms.append(feed[f]["cost"] * x[(c, d, f)])
            obj_terms.append(
                (aeration_fixed_cost + day[d]["power_cost"]) * h[(c, d)]
            )
    model.setObjective(quicksum(obj_terms), sense="minimize")

    # Solver settings
    model.setRealParam("limits/gap", 0.0005)
    tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if tl:
        try:
            tv = float(tl)
            if tv > 0:
                model.setRealParam("limits/time", tv)
        except Exception:
            pass

    model.optimize()

    status = model.getStatus()
    print("Solver status:", status)
    obj = model.getObjVal()
    print("Objective value:", obj)

    # Extract solution
    rows = []
    for c in cage_ids:
        for d in day_ids:
            for f in feed_ids:
                val = model.getVal(x[(c, d, f)])
                if val is None:
                    val = 0.0
                val = max(0.0, val)
                val = round(val, 8)
                if val > 1e-9:
                    rows.append(["feed", c, d, f, f"{val:.8f}"])
            val = model.getVal(h[(c, d)])
            if val is None:
                val = 0.0
            val = max(0.0, val)
            val = round(val, 8)
            if val > 1e-9:
                rows.append(["aeration", c, d, "", f"{val:.8f}"])

    out_path = os.path.join(SUB_DIR, "solution.csv")
    with open(out_path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["row_type", "cage_id", "day", "feed_id", "value"])
        for r in rows:
            w.writerow(r)

    print("Wrote", out_path, "with", len(rows), "nonzero rows")

    # Validation
    def total_feed(c, d):
        return sum(model.getVal(x[(c, d, f)]) or 0.0 for f in feed_ids)

    ok = True
    for c in cage_ids:
        for d in day_ids:
            app = cond_map[(c, d)]["appetite"]
            tf = total_feed(c, d)
            lo = cage[c]["min_feed"] * app
            hi = cage[c]["max_feed"] * app
            if tf < lo - eps or tf > hi + eps:
                ok = False
                print(f"Ration violation {c} {d}: {tf} not in [{lo},{hi}]")
            prot = sum(
                (model.getVal(x[(c, d, f)]) or 0.0) * feed[f]["protein"]
                for f in feed_ids
            ) / tf if tf > 0 else 0.0
            if prot < cage[c]["min_protein"] - eps:
                ok = False
                print(f"Protein violation {c} {d}: {prot}")
            hh = model.getVal(h[(c, d)]) or 0.0
            do = (
                day[d]["base_oxy"]
                + o2_gain * hh
                - cond_map[(c, d)]["o2sens"] * cage[c]["biomass"]
                - sum(
                    (model.getVal(x[(c, d, f)]) or 0.0) * feed[f]["o2load"]
                    for f in feed_ids
                )
            )
            if do < cage[c]["min_oxygen"] - eps:
                ok = False
                print(f"Oxygen violation {c} {d}: {do}")
    for d in day_ids:
        tf = sum(
            (model.getVal(x[(c, d, f)]) or 0.0)
            for c in cage_ids
            for f in feed_ids
        )
        if tf > day[d]["barge_cap"] + eps:
            ok = False
            print(f"Barge violation {d}: {tf}")
        ah = sum((model.getVal(h[(c, d)]) or 0.0) for c in cage_ids)
        if ah > day[d]["aer_limit"] + eps:
            ok = False
            print(f"Aeration violation {d}: {ah}")
        fm = sum(
            (model.getVal(x[(c, d, f)]) or 0.0) * feed[f]["fishmeal"]
            for c in cage_ids
            for f in feed_ids
        )
        if fm > day[d]["fishmeal_lim"] + eps:
            ok = False
            print(f"Fishmeal violation {d}: {fm}")

    print("Validation passed:", ok)


if __name__ == "__main__":
    main()
